svg.script:

const stepInfo=[
  {name:'1. Levantar',desc:'Inicia sentado com as costas apoiadas na cadeira, levantando-se ao sinal.'},
  {name:'2. Deslocamento (3m)',desc:'Caminha em linha reta por 3 metros em ritmo confortável e seguro.'},
  {name:'3. Giro / Retorno',desc:'Contorna o cone/marcador físico posicionado a exatamente 3 metros.'},
  {name:'4. Sentar',desc:'Retorna caminhando até a cadeira e senta-se, apoiando as costas.'}
];
let isDragging=false;
const track=document.getElementById('slider-hitbox');
const handle=document.getElementById('slider-handle');
const needle=document.getElementById('stopwatch-needle');
const timeVal=document.getElementById('time-value');
const riskBadge=document.getElementById('risk-badge');
const riskLabel=document.getElementById('risk-label');
const desc1=document.getElementById('risk-desc-1');
const desc2=document.getElementById('risk-desc-2');
const desc3=document.getElementById('risk-desc-3');
function setTime(t){
  t=Math.max(0,Math.min(40,t));
  const x=595+(t/40)*250;
  handle.setAttribute('cx',x);
  const angle=(t/40)*360;
  needle.setAttribute('transform',`rotate(${angle} 720 195)`);
  timeVal.textContent=t.toFixed(1)+' s';
  if(t<10){
    riskBadge.setAttribute('fill','var(--c-green)');
    riskLabel.setAttribute('fill','#ffffff');
    riskLabel.textContent='Mobilidade Normal (< 10s)';
    handle.setAttribute('fill','var(--c-green)');
    desc1.textContent='Indivíduo totalmente independente,';
    desc2.textContent='mobilidade preservada de forma ideal.';
    desc3.textContent='Baixo risco de quedas.';
  }else if(t<=20){
    riskBadge.setAttribute('fill','var(--c-amber)');
    riskLabel.setAttribute('fill','#12131a');
    riskLabel.textContent='Independência Parcial (10-20s)';
    handle.setAttribute('fill','var(--c-amber)');
    desc1.textContent='Indivíduo com independência parcial,';
    desc2.textContent='limitação física leve a moderada.';
    desc3.textContent='Atenção: risco de quedas moderado.';
  }else{
    riskBadge.setAttribute('fill','var(--c-red)');
    riskLabel.setAttribute('fill','#ffffff');
    riskLabel.textContent='Alto Risco de Queda (> 20s)';
    handle.setAttribute('fill','var(--c-red)');
    desc1.textContent='Mobilidade gravemente comprometida,';
    desc2.textContent='tempo limite crítico ultrapassado.';
    desc3.textContent='Alto risco de quedas detectado!';
  }
}
window.selectStep=function(idx){
  for(let i=0;i<4;i++){
    document.getElementById('hs-'+(i+1)).classList.toggle('active',i===idx);
    document.getElementById('path-'+(i+1)).classList.toggle('active',i===idx);
  }
  document.getElementById('step-title').textContent=stepInfo[idx].name;
  document.getElementById('step-desc').textContent=stepInfo[idx].desc;
  const defaultTimes=[2.5,7.2,14.5,24.8];
  setTime(defaultTimes[idx]);
};
function handleMove(e){
  if(!isDragging)return;
  const rect=document.getElementById('slider-track').getBoundingClientRect();
  const clientX=e.touches?e.touches[0].clientX:e.clientX;
  const pct=Math.max(0,Math.min(1,(clientX-rect.left)/rect.width));
  setTime(pct*40);
}
track.addEventListener('mousedown',e=>{isDragging=true;handleMove(e);});
track.addEventListener('touchstart',e=>{isDragging=true;handleMove(e);});
window.addEventListener('mousemove',handleMove);
window.addEventListener('touchmove',handleMove);
window.addEventListener('mouseup',()=>isDragging=false);
window.addEventListener('touchend',()=>isDragging=false);
selectStep(0);
